fn q_parts() void {
  const qall = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{2 * QH} -> qkv[i] });
  const qp0 = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{2 * QH} -> qpart[i] });
  if (NP == 1) { @fs2h(qp0, qall); return; }
  const qr = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{2 * QH} -> qres[i] });
  const qt = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{2 * QH} -> qtmp[i] });
  @fmovs(qr, qall);
  var k: u16 = 0;
  while (k < NP) : (k += 1) {
    const part = @increment_dsd_offset(qp0, @as(i16, k * 2 * QH), @fp16());
    @fs2h(part, qr);
    if (k + 1 < NP) {
      @fh2s(qt, part);
      @fsubs(qr, qr, qt);
    }
  }
}
